import{_ as t,c as a,o as s,ag as n}from"./chunks/framework.Bzez9NG9.js";const i="/space/img/1pythonrun.png",g=JSON.parse('{"title":"Python scripts","description":"Create, edit, run, and automate Python scripts in SPACE, including script arguments, execution output, errors, and scheduled execution through SPACE jobs.","frontmatter":{"title":"Python scripts","description":"Create, edit, run, and automate Python scripts in SPACE, including script arguments, execution output, errors, and scheduled execution through SPACE jobs.","keywords":["Python","Python scripts",".py","automation","script arguments","parameters","jobs","scheduling","output","traceback","IBM Planning Analytics","TM1"],"outline":"deep"},"headers":[],"relativePath":"doc/python/scripts.md","filePath":"doc/python/scripts.md"}'),r={name:"doc/python/scripts.md"};function o(c,e,p,h,d,u){return s(),a("div",null,e[0]||(e[0]=[n('<h1 id="python-scripts" tabindex="-1">Python scripts <a class="header-anchor" href="#python-scripts" aria-label="Permalink to &quot;Python scripts&quot;">​</a></h1><p>Use Python scripts in SPACE for reusable analysis, integrations, utilities, and automation. You can create and edit <code>.py</code> files in the Python workspace, run them interactively while developing, and use SPACE jobs when a script needs to run automatically.</p><p>For interactive analysis and development with executable cells, see <a href="./jupyter.html">Jupyter</a>.</p><h2 id="creating-and-editing-scripts" tabindex="-1">Creating and editing scripts <a class="header-anchor" href="#creating-and-editing-scripts" aria-label="Permalink to &quot;Creating and editing scripts&quot;">​</a></h2><p>Create a Python file from the launcher or open an existing <code>.py</code> file from the workspace.</p><p>The editor provides features such as syntax highlighting and code completion while you work. Save scripts in the Python workspace so they can be reused and, when appropriate, executed through SPACE jobs.</p><p><img src="'+i+'" alt="Script run and output" data-zoomable=""></p><h2 id="running-a-script" tabindex="-1">Running a script <a class="header-anchor" href="#running-a-script" aria-label="Permalink to &quot;Running a script&quot;">​</a></h2><p>Run a Python script directly from the editor when developing or testing it.</p><p>SPACE displays the script output below the editor, including standard output, logs, errors, and the execution status. This makes it possible to inspect results and Python tracebacks without leaving the workspace.</p><p>For example:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello SPACE!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>produces:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello SPACE!</span></span></code></pre></div><h2 id="script-arguments" tabindex="-1">Script arguments <a class="header-anchor" href="#script-arguments" aria-label="Permalink to &quot;Script arguments&quot;">​</a></h2><p>Scripts can be executed with arguments when input needs to vary between runs.</p><p>This is useful for reusable scripts where values such as an environment, object name, date, or processing option should be supplied at execution time rather than hard-coded into the script.</p><p>When no arguments are required, use <strong>Run without arguments</strong>.</p><h2 id="using-space-resources-from-scripts" tabindex="-1">Using SPACE resources from scripts <a class="header-anchor" href="#using-space-resources-from-scripts" aria-label="Permalink to &quot;Using SPACE resources from scripts&quot;">​</a></h2><p>Python scripts can use the <a href="./sdk.html">SPACE Python SDK</a> to work with supported SPACE-managed resources.</p><p>For scripts that require credentials or connection information, use <a href="./secrets-and-connections.html">Secrets and connections</a> rather than hard-coding sensitive values in Python files.</p><p>For IBM Planning Analytics automation, <a href="./tm1py.html">TM1py</a> can be combined with SPACE-managed connection configuration and credentials to create reusable TM1 scripts without maintaining credentials directly in the source code.</p><h2 id="scheduled-execution" tabindex="-1">Scheduled execution <a class="header-anchor" href="#scheduled-execution" aria-label="Permalink to &quot;Scheduled execution&quot;">​</a></h2><p>Use a <strong>Python script</strong> job when a stored script needs to run automatically.</p><p>A job can execute a Python file from the workspace and supply arguments when required. Configure its schedule and other job options under <a href="./../configuration/jobs.html">Settings → Jobs</a>.</p><p>This allows the same script to be run interactively during development and later reused for scheduled automation without maintaining a separate copy.</p>',26)]))}const m=t(r,[["render",o]]);export{g as __pageData,m as default};
